// Offline Supabase mock (localStorage)
// Supports all common query chains: .select().eq().eq().single() etc.

function generateID() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}
function getTable(t) {
  const d = localStorage.getItem(`bwanali_${t}`);
  return d ? JSON.parse(d) : [];
}
function saveTable(t, r) {
  localStorage.setItem(`bwanali_${t}`, JSON.stringify(r));
}

// Seed demo data once
if (!localStorage.getItem('bwanali_seeded')) {
  localStorage.setItem('bwanali_stores', JSON.stringify([{
    id: 'store-1', name: 'Demo Store', subscription_status: 'trialing',
    trial_started_at: new Date().toISOString(), subscription_plan: 'monthly', locked: false
  }]));
  localStorage.setItem('bwanali_staff', JSON.stringify([{
    id: 'staff-1', store_id: 'store-1', full_name: 'Admin Demo',
    email: 'admin@demo.com', role: 'admin', pin_code: '1234', is_active: true
  }]));
  localStorage.setItem('bwanali_products', JSON.stringify([
    { id: 'prod-1', store_id: 'store-1', name: 'Cooking Oil 2L', barcode:'111', category:'Groceries', unit_price:230, cost_price:210, stock_quantity:20, is_active:true },
    { id: 'prod-2', store_id: 'store-1', name: 'Sugar 1kg', barcode:'222', category:'Groceries', unit_price:38, cost_price:30, stock_quantity:100, is_active:true },
    { id: 'prod-3', store_id: 'store-1', name: 'Bread Loaf', barcode:'333', category:'Bakery', unit_price:25, cost_price:18, stock_quantity:50, is_active:true },
  ]));
  localStorage.setItem('bwanali_company_settings', JSON.stringify([{
    id:'settings-1', store_id:'store-1', company_name:'Demo Store Ltd', local_currency:'ZMW', receipt_footer:'Thank you!'
  }]));
  localStorage.setItem('bwanali_customers', '[]');
  localStorage.setItem('bwanali_sales', '[]');
  localStorage.setItem('bwanali_sale_items', '[]');
  localStorage.setItem('bwanali_cash_shifts', '[]');
  localStorage.setItem('bwanali_discount_rules', '[]');
  localStorage.setItem('bwanali_returns', '[]');
  localStorage.setItem('bwanali_laybys', '[]');
  localStorage.setItem('bwanali_seeded', 'true');
}

// ---------- Helper: thenable with .catch ----------
function Thenable(val) {
  const obj = {
    then: (resolve) => { resolve(val); },
    catch: () => obj,
  };
  return obj;
}

// ---------- Query builder ----------
function buildQuery(tableName) {
  const rows = getTable(tableName);
  const filters = [];
  let countReq = false, headOnly = false;

  const apply = () => {
    let list = [...rows];
    filters.forEach(f => {
      if (f.type === 'eq') list = list.filter(r => r[f.col] === f.val);
      else if (f.type === 'gte') list = list.filter(r => new Date(r[f.col]) >= new Date(f.val));
      else if (f.type === 'lte') list = list.filter(r => new Date(r[f.col]) <= new Date(f.val));
      else if (f.type === 'not') list = list.filter(r => r[f.col] !== f.val);
      else if (f.type === 'is') list = list.filter(r => r[f.col] === null);
    });
    return list;
  };

  const chain = {
    eq: (col, val) => { filters.push({ type: 'eq', col, val }); return chain; },
    gte: (col, val) => { filters.push({ type: 'gte', col, val }); return chain; },
    lte: (col, val) => { filters.push({ type: 'lte', col, val }); return chain; },
    not: (col, val) => { filters.push({ type: 'not', col, val }); return chain; },
    is: (col, val) => { filters.push({ type: 'is', col, val }); return chain; },
    order: (col, opt = {}) => {
      const list = apply();
      list.sort((a, b) => (a[col] > b[col] ? 1 : -1) * (opt.ascending !== false ? 1 : -1));
      return Thenable({ data: list, error: null });
    },
    single: () => {
      const list = apply();
      return Thenable({ data: list[0] || null, error: null });
    },
    maybeSingle: () => {
      const list = apply();
      return Thenable({ data: list[0] || null, error: null });
    },
    limit: (n) => {
      const list = apply().slice(0, n);
      const result = countReq ? { count: headOnly ? apply().length : list.length, data: headOnly ? [] : list } : { data: list, error: null };
      return Thenable(result);
    },
    then: (resolve) => {
      const list = apply();
      resolve(countReq ? { count: list.length, data: list } : { data: list, error: null });
    },
    catch: () => {},
  };

  return { chain, setCount: () => { countReq = true; }, setHead: () => { headOnly = true; } };
}

// ---------- Supabase-like object ----------
const fake = {
  from: (table) => {
    const query = buildQuery(table);

    return {
      select: (cols, options) => {
        if (options && options.count === 'exact') {
          query.setCount();
          if (options.head) query.setHead();
        }
        return query.chain;
      },
      insert: (data) => {
        const arr = Array.isArray(data) ? data : [data];
        const newRows = arr.map(d => ({ id: generateID(), ...d }));
        const current = getTable(table);
        saveTable(table, [...current, ...newRows]);
        return Thenable({ data: newRows, error: null });
      },
      update: (data) => ({
        eq: (col, val) => {
          const rows = getTable(table);
          const updated = rows.map(r => r[col] === val ? { ...r, ...data } : r);
          saveTable(table, updated);
          return Thenable({ error: null });
        },
        in: (col, vals) => {
          const rows = getTable(table);
          const updated = rows.map(r => vals.includes(r[col]) ? { ...r, ...data } : r);
          saveTable(table, updated);
          return Thenable({ error: null });
        },
      }),
      delete: () => ({
        eq: (col, val) => {
          const rows = getTable(table);
          saveTable(table, rows.filter(r => r[col] !== val));
          return Thenable({ error: null });
        },
      }),
      upsert: (data) => {
        const rows = getTable(table);
        (Array.isArray(data) ? data : [data]).forEach(d => {
          const idx = rows.findIndex(r => r.id === d.id);
          if (idx >= 0) rows[idx] = d;
          else rows.push({ id: generateID(), ...d });
        });
        saveTable(table, rows);
        return Thenable({ error: null });
      },
    };
  },
  auth: {
    signInWithPassword: async ({ email, password }) => {
      const staff = getTable('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      localStorage.setItem('local_user', JSON.stringify(user));
      return { data: { user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error: null }; },
    getSession: async () => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      if (!user) return { data: { session: null } };
      return { data: { session: { user, access_token: 'offline', refresh_token: 'offline' } } };
    },
    onAuthStateChange: (cb) => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      setTimeout(() => cb('SIGNED_IN', { user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => ({ error: null }),
    signUp: async ({ email, password, options }) => {
      const staff = getTable('staff');
      const newUser = { id: generateID(), email, pin_code: password, full_name: options?.data?.full_name || 'New User', role: 'cashier', is_active: true, store_id: null };
      saveTable('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    },
  },
  storage: {
    from: () => ({
      upload: async () => ({ error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  },
  rpc: () => Thenable({ error: null }),
};

export const supabase = fake;
